class Node:
    """즉시 계산(eager)하는 작은 노드: 값·기울기·부모와 지역 미분."""
    def __init__(self, value, parents=()):
        self.value, self.grad, self.parents = value, 0.0, parents
    def __add__(self, o): return Node(self.value + o.value, ((self, 1.0), (o, 1.0)))
    def sq(self):         return Node(self.value ** 2, ((self, 2 * self.value),))
    def detach(self):     return Node(self.value)          # 값만 복사, 부모 끊김

def backward(root):
    order, seen = [], set()
    def visit(n):
        if id(n) in seen: return
        seen.add(id(n))
        for p, _ in n.parents: visit(p)
        order.append(n)
    visit(root); root.grad = 1.0
    for n in reversed(order):                # 위상 역순으로 연쇄 법칙
        for p, local in n.parents:
            p.grad += local * n.grad

x = Node(1.0); y = x.sq(); z = y.sq()       # 노드로 쓰기
u = Node(3.0)
l2 = y.detach().sq() + u                     # 값으로 쓰기
backward(l2)
print("l2 =", l2.value, "u.grad =", u.grad, "x.grad =", x.grad)  # 4.0 1.0 0.0
backward(z)
print("z 로 역전파하면 x.grad =", x.grad)    # 4.0 (= 4x^3)
